import{_ as e,o,c as d,ag as r}from"./chunks/framework.BPmc_f4o.js";const p=JSON.parse('{"title":"Keyboard Shortcuts","description":"Editor and layout keyboard shortcuts for the Muxit web UI.","frontmatter":{"title":"Keyboard Shortcuts","description":"Editor and layout keyboard shortcuts for the Muxit web UI."},"headers":[],"relativePath":"guides/keyboard-shortcuts.md","filePath":"guides/keyboard-shortcuts.md"}'),c={name:"guides/keyboard-shortcuts.md"};function a(n,t,i,l,s,u){return o(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h1><h2 id="editor" tabindex="-1">Editor <a class="header-anchor" href="#editor" aria-label="Permalink to &quot;Editor&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+S</code></td><td>Save current file</td></tr><tr><td><code>Ctrl+Z</code></td><td>Undo</td></tr><tr><td><code>Ctrl+Shift+Z</code></td><td>Redo</td></tr><tr><td><code>Ctrl+/</code></td><td>Toggle line comment</td></tr><tr><td><code>Ctrl+D</code></td><td>Select next occurrence</td></tr><tr><td><code>Ctrl+F</code></td><td>Find</td></tr><tr><td><code>Ctrl+H</code></td><td>Find and replace</td></tr><tr><td><code>Ctrl+G</code></td><td>Go to line</td></tr><tr><td><code>Ctrl+Shift+K</code></td><td>Delete line</td></tr><tr><td><code>Alt+Up/Down</code></td><td>Move line up/down</td></tr><tr><td><code>Ctrl+Shift+Up/Down</code></td><td>Copy line up/down</td></tr><tr><td><code>Tab</code></td><td>Indent / accept autocomplete</td></tr><tr><td><code>Shift+Tab</code></td><td>Outdent</td></tr></tbody></table><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>Ctrl+B</code></td><td>Toggle primary sidebar</td></tr><tr><td><code>Ctrl+Shift+B</code></td><td>Toggle secondary sidebar</td></tr><tr><td><code>Ctrl+J</code></td><td>Toggle output panel</td></tr><tr><td><code>Alt+Z</code></td><td>Toggle editor word wrap</td></tr><tr><td><code>Ctrl+,</code></td><td>Open settings</td></tr><tr><td><code>Ctrl+N</code></td><td>New file</td></tr><tr><td><code>Ctrl+1</code>..<code>Ctrl+9</code></td><td>Focus editor group by index</td></tr></tbody></table><h2 id="script-execution" tabindex="-1">Script Execution <a class="header-anchor" href="#script-execution" aria-label="Permalink to &quot;Script Execution&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td>Run button</td><td>Execute current script</td></tr><tr><td>Stop button</td><td>Abort running script</td></tr></tbody></table><h2 id="intellisense" tabindex="-1">IntelliSense <a class="header-anchor" href="#intellisense" aria-label="Permalink to &quot;IntelliSense&quot;">​</a></h2><p>The editor provides context-aware IntelliSense for the Muxit API:</p><h3 id="autocomplete" tabindex="-1">Autocomplete <a class="header-anchor" href="#autocomplete" aria-label="Permalink to &quot;Autocomplete&quot;">​</a></h3><ul><li>Type <code>connector(&quot;</code> or <code>device(&quot;</code> to see available connector names</li><li>Type <code>connector(&quot;name&quot;).</code> to see properties and actions for a device</li><li>Type <code>log.</code> to see logging methods (<code>info</code>, <code>warn</code>, <code>error</code>, <code>debug</code>)</li><li>Type <code>script.</code> to see lifecycle properties (<code>running</code>, <code>name</code>)</li><li>Type <code>on(&quot;</code> or <code>emit(&quot;</code> to see known event name patterns</li><li>Type <code>stream(&quot;</code> to see connector names for streaming</li><li>All sandbox globals (<code>connector</code>, <code>delay</code>, <code>emit</code>, <code>ai</code>, <code>say</code>, <code>timestamp</code>, etc.) appear as top-level suggestions</li></ul><h3 id="hover-documentation" tabindex="-1">Hover Documentation <a class="header-anchor" href="#hover-documentation" aria-label="Permalink to &quot;Hover Documentation&quot;">​</a></h3><p>Hover over any sandbox global (<code>connector</code>, <code>delay</code>, <code>ai</code>, <code>log</code>, etc.) to see its signature and description. Hovering over a connector property or action (after <code>connector(&quot;name&quot;).</code>) shows its type, access level, and documentation.</p><h3 id="signature-help" tabindex="-1">Signature Help <a class="header-anchor" href="#signature-help" aria-label="Permalink to &quot;Signature Help&quot;">​</a></h3><p>Type <code>(</code> after a function name to see parameter hints. Press <code>,</code> to cycle through parameters. Works for all sandbox globals and connector actions with their argument types.</p><h3 id="context-awareness" tabindex="-1">Context Awareness <a class="header-anchor" href="#context-awareness" aria-label="Permalink to &quot;Context Awareness&quot;">​</a></h3><p>IntelliSense adapts based on file location:</p><ul><li><strong>Script files</strong> (<code>scripts/*.js</code>): Full script sandbox API including <code>ai()</code>, <code>say()</code>, <code>on()</code>, <code>stream()</code>, <code>script.*</code></li><li><strong>Connector configs</strong> (<code>connectors/*.js</code>): Connector sandbox API including <code>createTcpTransport()</code>, <code>createSerialTransport()</code></li><li><strong>Other <code>.js</code> files</strong>: All globals from both contexts</li></ul>',18)])])}const b=e(c,[["render",a]]);export{p as __pageData,b as default};
